// AI Tutorial Generator - Job Status Tracker
// Polls the BACKEND directly (same as Google Doc extension).
// The Moodle DB is only used for initial render; live status comes from the backend.

define('mod_aitutorial/job_tracker', ['jquery', 'core/notification'], function($, Notification) {

    var BACKEND_URL = 'https://cuppai.top';

    /**
     * Initialize job tracker.
     * @param {number} cmid Course module ID (unused for backend polling, kept for compat)
     * @param {string} apiBaseUrl Backend API base URL (configured in plugin settings)
     */
    function init(cmid, apiBaseUrl) {
        if (apiBaseUrl) {
            BACKEND_URL = String(apiBaseUrl).replace(/\/+$/, '');
        }
        console.log('Cuppa AI: Job tracker initialized (polling ' + BACKEND_URL + ')');

        // Poll every 5 seconds, same interval as Google Doc extension.
        setInterval(function() {
            pollAllActiveJobs();
        }, 5000);
    }

    /**
     * Poll backend for every job card that is still processing.
     * Mirrors Google Doc extension's pollStatus() logic.
     */
    function pollAllActiveJobs() {
        var idToken = window.cuppaIdToken || null;

        $('.aitutorial-job-card').each(function() {
            var jobCard = $(this);
            var badge = jobCard.find('.badge');

            // Only poll jobs that are still in-progress.
            if (!badge.hasClass('status-processing') && !badge.hasClass('status-pending')) {
                return;
            }

            // Each job card stores the backend job_id in data-backendid.
            // If missing (old jobs), fall back to Moodle DB via status.php.
            var backendJobId = jobCard.data('backendid');

            if (backendJobId && idToken) {
                pollBackend(jobCard, backendJobId, idToken);
            } else {
                // Fallback: poll Moodle DB (for jobs started before this fix)
                var moodleJobId = jobCard.data('jobid');
                pollMoodle(jobCard, moodleJobId);
            }
        });
    }

    /**
     * Poll the backend /api/status/{job_id} directly with Firebase token.
     * Identical flow to Google Doc extension's checkStatus().
     */
    function pollBackend(jobCard, backendJobId, idToken) {
        $.ajax({
            url: BACKEND_URL + '/api/status/' + backendJobId,
            type: 'GET',
            headers: { 'Authorization': 'Bearer ' + idToken },
            dataType: 'json',
            success: function(data) {
                if (data.error) {
                    console.error('Backend poll error for job', backendJobId, data.error);
                    return;
                }
                updateJobCard(jobCard, data);
            },
            error: function(xhr) {
                console.error('Backend poll failed for job', backendJobId, xhr.status, xhr.statusText);
            }
        });
    }

    /**
     * Fallback: poll local Moodle status.php (for legacy jobs without backend ID).
     */
    function pollMoodle(jobCard, moodleJobId) {
        $.ajax({
            url: M.cfg.wwwroot + '/mod/aitutorial/api/status.php',
            type: 'GET',
            data: { jobid: moodleJobId, sesskey: M.cfg.sesskey },
            dataType: 'json',
            success: function(data) {
                if (data.error) {
                    console.error('Moodle poll error for job', moodleJobId, data.error);
                    return;
                }
                updateJobCard(jobCard, data);
            },
            error: function(xhr) {
                console.error('Moodle poll failed for job', moodleJobId, xhr.status);
            }
        });
    }

    /**
     * Update job card UI with latest status from backend.
     * @param {jQuery} jobCard
     * @param {Object} data  Response from backend or Moodle DB
     */
    function updateJobCard(jobCard, data) {
        var badge = jobCard.find('.badge');

        // Map backend statuses to Moodle display labels.
        var statusLabels = {
            'pending':     'Pending',
            'ai_thinking': 'AI Thinking...',
            'processing':  'Processing',
            'rendering':   'Rendering',
            'completed':   'Completed',
            'failed':      'Failed'
        };

        // Update progress bar if available.
        var progress = data.progress || 0;
        var progressBar = jobCard.find('.progress-bar');
        var progressText = jobCard.find('.progress-text');
        if (progressBar.length) {
            progressBar.css('width', progress + '%').attr('aria-valuenow', progress);
        }
        if (progressText.length) {
            progressText.text(progress + '% complete');
        }

        // Update status badge.
        var status = data.status;
        if (status && status !== 'processing' && status !== 'pending') {
            badge.removeClass('status-processing status-pending status-ai_thinking status-rendering')
                 .addClass('status-' + status)
                 .text(statusLabels[status] || status);

            // Reload page when done so Moodle shows the video/poster links.
            if (status === 'completed' || status === 'failed') {
                var errorMsg = data.error || '';
                if (status === 'failed' && errorMsg) {
                    console.error('Job failed:', errorMsg);
                }
                setTimeout(function() {
                    location.reload();
                }, 2000);
            }
        } else if (status === 'ai_thinking' || status === 'rendering') {
            // Show intermediate states on the badge.
            badge.text(statusLabels[status] || status);
        }
    }

    // Retry button handler.
    $(document).on('click', '.btn-retry', function() {
        var jobid = $(this).data('jobid');
        if (!confirm('Are you sure you want to retry this generation?')) {
            return;
        }
        $.ajax({
            url: M.cfg.wwwroot + '/mod/aitutorial/api/retry.php',
            type: 'POST',
            data: { jobid: jobid, sesskey: M.cfg.sesskey },
            dataType: 'json',
            success: function(response) {
                if (response.success) {
                    Notification.addNotification({
                        message: 'Regeneration started. Page will refresh...',
                        type: 'success'
                    });
                    setTimeout(function() { location.reload(); }, 3000);
                } else {
                    alert('Retry failed: ' + (response.error || 'Unknown error'));
                }
            },
            error: function() {
                alert('Could not reach server to retry.');
            }
        });
    });

    return { init: init };
});
